-- Migration: Seed discovery_place_overrides data from local to production
-- Safe to run on production: uses INSERT ... ON CONFLICT (place_id) DO UPDATE
-- so existing rows are updated, new rows are inserted, no duplicates created.
-- 29 records from local Bengaluru discovery override dataset.

ON CONFLICT (place_id) DO UPDATE SET
  name_override        = EXCLUDED.name_override,
  address_override     = EXCLUDED.address_override,
  latitude_override    = EXCLUDED.latitude_override,
  longitude_override   = EXCLUDED.longitude_override,
  image_path           = EXCLUDED.image_path,
  image_source         = EXCLUDED.image_source,
  google_photo_reference = EXCLUDED.google_photo_reference,
  description_override = EXCLUDED.description_override,
  category_override    = EXCLUDED.category_override,
  provider             = EXCLUDED.provider,
  is_deleted           = EXCLUDED.is_deleted,
  subcategory          = EXCLUDED.subcategory,
  updated_at           = EXCLUDED.updated_at;
